<!-- Generated by bildr from .bildr/modules/blog/pages/index.json. Editing this file detaches it from the editor; prefer overriding it from the root app/. -->
<script setup lang="ts">
definePageMeta({ name: 'index', layout: 'main' })
useSeoMeta({ title: 'Blog' })

const { preferences, set } = useBlogPreferences()
const featured = useFeaturedPosts(6)
const all = useAllPosts()
const quotes = useLatestQuotes(3)

const posts = computed(() => preferences.value.showDrafts ? all.data.value : featured.data.value)
const isLoading = computed(() => featured.isLoading.value || all.isLoading.value)
</script>

<template>
  <section class="flex flex-col gap-6">
    <div class="flex items-center justify-between">
      <h1 class="text-3xl font-semibold">Posts</h1>
      <label class="flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          :checked="preferences.showDrafts"
          data-test="show-drafts"
          @change="set({ showDrafts: ($event.target as HTMLInputElement).checked })"
        >
        Show drafts
      </label>
    </div>

    <p v-if="isLoading" class="text-muted">Loading…</p>
    <p v-else-if="!posts.length" class="text-muted">No posts yet.</p>
    <div v-else class="grid gap-4 sm:grid-cols-2" data-test="post-list">
      <BlogPostCard v-for="post in posts" :key="post.id" :post="post" />
    </div>

    <aside v-if="quotes.data.value.length" class="flex flex-col gap-2 border-t border-border pt-6">
      <h2 class="text-sm font-semibold uppercase text-muted">Quotes</h2>
      <blockquote v-for="quote in quotes.data.value" :key="quote.id" class="text-sm">
        “{{ quote.text }}” — {{ quote.author }}
      </blockquote>
    </aside>
  </section>
</template>
